fn is_png_accepts_the_magic_and_rejects_a_black_hole() {
    assert!(is_png(&PNG_MAGIC));
    assert!(!is_png(b""), "a capture that wrote nothing must not read as a PNG");
    assert!(!is_png(b"not-an-image"));
